require __DIR__.'/includes/config.php'; require __DIR__.'/includes/database.php'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){$email=trim($_POST['email']??'');$password=$_POST['password']??'';$pdo=db();if($pdo){$st=$pdo->prepare('SELECT id,name,email,password_hash FROM users WHERE email=? LIMIT 1');$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($password,$u['password_hash'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email']];header('Location:index.php');exit;}else$error='Invalid email or password.';}else{$_SESSION['user']=['id'=>0,'name'=>'Demo Traveler','email'=>$email?:'demo@example.com'];header('Location:index.php');exit;}}
$pageTitle='Login'; require __DIR__.'/includes/header.php'; ?>
<div class="container"><div class="auth-card"><div class="section-kicker">Welcome back</div><h2 class="section-title">Login</h2><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><form method="post"><label class="form-label">Email</label><input required type="email" name="email" class="form-control mb-3"><label class="form-label">Password</label><input required type="password" name="password" class="form-control mb-3"><button class="btn btn-brand w-100">Login</button></form><p class="small muted mt-3 mb-0">No database? Demo mode signs you in locally. <a href="register.php">Register</a></p></div></div>
